VRFW.dual_element_enemy_layer = 222949092 --[[soccer01_06_p1_element_icon_enemy]]
VRFW.dual_element_cmd = 1129235707
VRFW.dual_element_wheel_cmd = 3994210558

-- the move's elements for this executor (a list of 2-4), nil = no dual element (retail)
function VRFW.dual_element_list(chara, skill)
  if chara == nil or skill == nil or skill == 0 then
    return nil
  end
  local n, e1, e2, e3, e4 = VRFW.host.command(VRFW.dual_element_cmd, chara, skill)
  if type(n) ~= "number" or n < 2 then
    return nil
  end
  local l = {}
  for _, e in ipairs({e1, e2, e3, e4}) do
    if #l < n and #l < VRFW.dual_element_max and type(e) == "number" and e > 0 then
      l[#l + 1] = e
    end
  end
  if #l < 2 then
    return nil
  end
  return l
end

-- the move's table element (retail CMND_GET_SOCCER_SKILL_INFO, field 7) as a one-element list
local function dual_element_table(skill)
  if skill == nil or skill == 0 then
    return {}
  end
  local _, e = VRFW.host.command(2580586398, skill, 7)
  if type(e) == "number" and e > 0 then
    return {e}
  end
  return {}
end

local function dual_element_set_icon(layer, index, e)
  local icon = 0
  if type(GetElementIcon) == "function" then
    local ok, v = pcall(GetElementIcon, e)
    if ok and v ~= nil then
      icon = v
    end
  end
  if icon == 0 then
    return
  end
  VRFW.host.menu_command(558735651, layer, 502529699 --[[#/menu/200_icon/15_icon_common/<LG>/icon_common.g4tx]], icon, 3530469477 --[[icon_type_dmy02]], 0, index)
end

-- Place one instance at row position k (0-based, left to right) of n, retail size, same y.
local function dual_element_place(layer, index, k, n)
  local x = (k - (n - 1)) * VRFW.dual_element_pitch
  if layer ~= VRFW.dual_element_enemy_layer then
    x = k * VRFW.dual_element_pitch
  end
  VRFW.host.menu_command(1389957207, layer, x, 0, 0, index)
end

local function dual_element_reset(layer, index)
  VRFW.host.menu_command(1389957207, layer, 0, 0, 0, index)
end

local dual_element_prev_icon = SetupVsElementIconLayerMenu
function SetupVsElementIconLayerMenu(a1, a2, a3, a4, a5, ...)
  local extra = type(a2) == "number" and a2 >= 2
  local l
  if extra or a3 == 1 then
    local ok, v = pcall(VRFW.dual_element_list, a4, a5)
    if ok then
      l = v
    end
  end
  local r = {n = 0}
  if type(dual_element_prev_icon) == "function" then
    if extra and l ~= nil and a2 <= #l then
      -- An extra icon of a dual move.
      r = table.pack(dual_element_prev_icon(a1, a2, 1, a4, a5, ...))
    else
      r = table.pack(dual_element_prev_icon(a1, a2, a3, a4, a5, ...))
    end
  end
  pcall(function()
    if extra then
      if l == nil or a2 > #l then
